s += '''\n// Local R18 plugin ownership evidence: a pinned fake module with controlled quiescence.\nTEST_F(R18ParserAdapterTest, ModuleConfigReferenceOnFailedAndSuccessfulInit)\n{\n    const fs::path fixture = "/tmp/wt-i03-r18-006-012/plugin/libR130LifecycleParser.dylib";\n    ASSERT_TRUE(fs::exists(fixture));\n    const fs::path local = fs::current_path() / "libR130LifecycleParser.dylib";\n    fs::copy_file(fixture, local, fs::copy_options::overwrite_existing);\n    void* handle = dlopen(local.c_str(), RTLD_NOW);\n    ASSERT_NE(handle, nullptr) << dlerror();\n    using Counter = uint32_t (*)();\n    using Reset = void (*)();\n    auto reset = reinterpret_cast<Reset>(dlsym(handle, "r130_parser_reset_counts"));\n    auto quiet = reinterpret_cast<Reset>(dlsym(handle, "r130_parser_prove_quiescent"));\n    auto init = reinterpret_cast<Counter>(dlsym(handle, "r130_parser_init_count"));\n    auto sub = reinterpret_cast<Counter>(dlsym(handle, "r130_parser_subscribe_count"));\n    auto connect = reinterpret_cast<Counter>(dlsym(handle, "r130_parser_connect_count"));\n    auto rel = reinterpret_cast<Counter>(dlsym(handle, "r130_parser_release_count"));\n    auto del = reinterpret_cast<Counter>(dlsym(handle, "r130_parser_delete_count"));\n    ASSERT_TRUE(reset && quiet && init && sub && connect && rel && del);\n    for (bool initOk : {false, true})\n    {\n        reset();\n        WTSVariant* cfg = WTSVariant::createObject();\n        cfg->append("module", "R130LifecycleParser");\n        cfg->append("r130_init_ok", initOk);\n        const uint32_t baseline = cfg->retainCount();\n        {\n            ParserAdapter pa(&_bdMgr, &_dm, nullptr);\n            EXPECT_EQ(pa.init("r18_cfg_lifecycle", cfg), initOk);\n            EXPECT_EQ(cfg->retainCount(), baseline + 1);\n            EXPECT_EQ(init(), 1u);\n            EXPECT_EQ(sub(), initOk ? 1u : 0u);\n            if (!initOk) { EXPECT_FALSE(pa.run()); EXPECT_EQ(connect(), 0u); }\n            quiet();\n            pa.release();\n            EXPECT_EQ(cfg->retainCount(), baseline);\n            EXPECT_EQ(rel(), 1u);\n            EXPECT_EQ(del(), 1u);\n            pa.release();\n            EXPECT_EQ(rel(), 1u);\n            EXPECT_EQ(del(), 1u);\n        }\n        EXPECT_EQ(cfg->retainCount(), baseline);\n        cfg->release();\n    }\n    dlclose(handle);\n    fs::remove(local);\n}\n'''
p.write_text(s)
